:root {
  --bg: #1a1c2c;
  --panel: #29366f;
  --accent: #41a6f6;
  --text: #f4f4f4;
  --muted: #94b0c2;
  --danger: #ef7d57;
}
* { box-sizing: border-box; }
[hidden] { display: none !important; }
body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  background: var(--bg);
  background-image: linear-gradient(45deg, #22243a 25%, transparent 25%, transparent 75%, #22243a 75%),
                    linear-gradient(45deg, #22243a 25%, transparent 25%, transparent 75%, #22243a 75%);
  background-size: 32px 32px;
  background-position: 0 0, 16px 16px;
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
}
.card {
  width: 100%;
  max-width: 480px;
  background: var(--panel);
  border: 4px solid var(--accent);
  border-radius: 0;
  padding: 24px;
  box-shadow: 8px 8px 0 #0f1020;
}
h1 {
  margin: 0 0 8px;
  font-size: 28px;
  letter-spacing: 1px;
  text-transform: uppercase;
  color: var(--accent);
}
.counts {
  margin: 0 0 20px;
  color: var(--muted);
  font-size: 16px;
}
.counts span { color: var(--text); font-weight: 700; }
.input-row { display: flex; gap: 8px; margin-bottom: 20px; }
input[type="text"] {
  flex: 1;
  min-width: 0;
  padding: 10px 12px;
  font-size: 16px;
  color: var(--text);
  background: #1a1c2c;
  border: 3px solid var(--muted);
  border-radius: 0;
  outline: none;
}
input[type="text"]:focus { border-color: var(--accent); }
button {
  font-family: inherit;
  font-size: 16px;
  font-weight: 700;
  padding: 10px 16px;
  color: var(--bg);
  background: var(--accent);
  border: 3px solid var(--accent);
  border-radius: 0;
  cursor: pointer;
  text-transform: uppercase;
  transition: transform 0.05s, background 0.15s;
}
button:hover { background: #6fc3ff; border-color: #6fc3ff; }
button:focus-visible { outline: 3px solid var(--text); outline-offset: 2px; }
button:active { transform: translate(2px, 2px); }
.todo-list { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 8px; }
.todo-list li {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 12px;
  background: #1a1c2c;
  border: 3px solid var(--muted);
}
.todo-list li.done .todo-text { text-decoration: line-through; color: var(--muted); }
.todo-text { flex: 1; word-break: break-word; }
.todo-list input[type="checkbox"] {
  width: 22px;
  height: 22px;
  accent-color: var(--accent);
  cursor: pointer;
}
.todo-delete {
  padding: 6px 10px;
  font-size: 16px;
  background: var(--danger);
  border-color: var(--danger);
}
.todo-delete:hover { background: #ff9a7a; border-color: #ff9a7a; }
.empty { margin: 16px 0 0; color: var(--muted); text-align: center; }
.visually-hidden {
  position: absolute; width: 1px; height: 1px;
  padding: 0; margin: -1px; overflow: hidden;
  clip: rect(0 0 0 0); white-space: nowrap; border: 0;
}
@media (max-width: 400px) {
  .card { padding: 16px; }
  h1 { font-size: 24px; }
}

const input = document.getElementById('todo-input');
const addBtn = document.getElementById('todo-add');
const form = document.getElementById('todo-form');
const list = document.getElementById('todo-list');
const totalEl = document.getElementById('todo-total');
const remainingEl = document.getElementById('remaining');
const emptyMsg = document.getElementById('empty-msg');

let tasks = [];
let nextId = 1;

function updateCounts() {
  const total = tasks.length;
  const remaining = tasks.filter(t => !t.done).length;
  totalEl.textContent = String(total);
  remainingEl.textContent = String(remaining);
  emptyMsg.hidden = total > 0;
}

function render() {
  list.innerHTML = '';
  tasks.forEach(task => {
    const li = document.createElement('li');
    li.dataset.id = String(task.id);
    if (task.done) li.classList.add('done');

    const check = document.createElement('input');
    check.type = 'checkbox';
    check.id = 'todo-check-' + task.id;
    check.checked = task.done;
    check.setAttribute('aria-label', 'Mark "' + task.text + '" as complete');
    check.addEventListener('change', () => {
      task.done = check.checked;
      li.classList.toggle('done', task.done);
      updateCounts();
    });

    const span = document.createElement('span');
    span.className = 'todo-text';
    span.id = 'todo-text-' + task.id;
    span.textContent = task.text;

    const del = document.createElement('button');
    del.type = 'button';
    del.id = 'todo-delete-' + task.id;
    del.className = 'todo-delete';
    del.textContent = 'X';
    del.setAttribute('aria-label', 'Delete "' + task.text + '"');
    del.addEventListener('click', () => {
      tasks = tasks.filter(t => t.id !== task.id);
      render();
    });

    li.append(check, span, del);
    list.appendChild(li);
  });
  updateCounts();
}

function addTask() {
  const text = input.value.trim();
  if (!text) return;
  tasks.push({ id: nextId++, text, done: false });
  input.value = '';
  input.focus();
  render();
}

form.addEventListener('submit', (e) => {
  e.preventDefault();
  addTask();
});

render();
